-- Profile iplant-block-extraction-v1; SELECT only. Bind @EstateID, @FromDate, @ToDate and @Year.
SELECT ModID,ModName,ModCode FROM General.Module;
SELECT AYear,ModID,MIN(AMonth) FirstPeriod,MAX(AMonth) LastPeriod,COUNT(*) PeriodRows FROM General.ActiveMonthYear WHERE EstateID=@EstateID GROUP BY AYear,ModID ORDER BY AYear,ModID;
SELECT YEAR(DDate) CalendarYear,Type,COUNT(*) Rows,COUNT(DISTINCT BlockID) Blocks,MIN(DDate) FirstDate,MAX(DDate) LastDate,SUM(MilWeight) WeightRaw,SUM(Bunches) Bunches FROM Checkroll.CropStatement WHERE EstateID=@EstateID GROUP BY YEAR(DDate),Type ORDER BY CalendarYear,Type;
SELECT YEAR(a.RDate) CalendarYear,COUNT(*) ReceptionRows,COUNT(DISTINCT r.BlockID) Blocks,COUNT(DISTINCT a.EmpID) Harvesters,MIN(a.RDate) FirstDate,MAX(a.RDate) LastDate,SUM(r.NActualBunches+r.BActualBunches) HeaderBunches FROM Checkroll.DailyReceiption r JOIN Checkroll.DailyAttendance a ON a.DailyReceiptionID=r.DailyReceiptionID AND a.EstateID=r.EstateID WHERE r.EstateID=@EstateID GROUP BY YEAR(a.RDate) ORDER BY CalendarYear;
SELECT YEAR(i.SIVDate) CalendarYear,i.Status,COUNT(*) DetailRows,COUNT(DISTINCT i.STIssueID) Vouchers,COUNT(DISTINCT d.BlockID) Blocks,SUM(d.IssuedValue) IssuedValue,MIN(i.SIVDate) FirstDate,MAX(i.SIVDate) LastDate FROM Store.STIssue i JOIN Store.STIssueDetails d ON d.STIssueID=i.STIssueID AND d.EstateID=i.EstateID WHERE i.EstateID=@EstateID GROUP BY YEAR(i.SIVDate),i.Status ORDER BY CalendarYear,i.Status;
SELECT YEAR(LogDate) CalendarYear,COUNT(*) Rows,COUNT(DISTINCT BlockID) Blocks,COUNT(DISTINCT VHID) Vehicles,MIN(LogDate) FirstDate,MAX(LogDate) LastDate FROM Vehicle.VHRunningLog WHERE EstateID=@EstateID GROUP BY YEAR(LogDate) ORDER BY CalendarYear;
SELECT AYear,ModID,COUNT(*) HeaderRows,MIN(LedgerDate) FirstDate,MAX(LedgerDate) LastDate FROM Accounts.LedgerAllModule WHERE EstateID=@EstateID GROUP BY AYear,ModID ORDER BY AYear,ModID;
SELECT YEAR(TransDate) CalendarYear,COUNT(*) Rows,COUNT(DISTINCT Block) Blocks,MIN(TransDate) FirstDate,MAX(TransDate) LastDate,SUM(DebitValue) Debit,SUM(CreditValue) Credit FROM dbo.CheckrollTemp WHERE Location=@EstateID GROUP BY YEAR(TransDate) ORDER BY CalendarYear;
SELECT AYear,LedgerType,COUNT(*) Rows,COUNT(DISTINCT BlackName) BlockNames,SUM(Debit) Debit,SUM(Credit) Credit FROM dbo.AllLedgerCOAReportDetails WHERE EstateID=@EstateID GROUP BY AYear,LedgerType ORDER BY AYear,LedgerType;
SELECT b.BlockID,b.BlockName,d.DivName,y.YOP,b.PlantedHect,b.Original,b.StandPerHect,b.SoilType,b.PlantingMaterial,b.BlockStatus FROM General.BlockMaster b LEFT JOIN General.Division d ON d.DivID=b.DivID AND d.EstateID=b.EstateID LEFT JOIN General.YOP y ON y.YOPID=b.YOPID AND y.EstateID=b.EstateID WHERE b.EstateID=@EstateID ORDER BY b.BlockName;
SELECT STCategoryID,STCategoryCode,STCategoryDescp FROM Store.STCategory WHERE EstateID=@EstateID;
SELECT s.name SchemaName,t.name TableName,c.name ColumnName,ty.name DataType FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE t.name IN ('STIssueDetails','STIssue','DailyReceptionWithTeam','CropStatement','CheckrollTemp') ORDER BY s.name,t.name,c.column_id;
